    private static JsonElement Required(JsonElement value, string name)
    {
        if (value.ValueKind != JsonValueKind.Object || !value.TryGetProperty(name, out var property) || property.ValueKind == JsonValueKind.Null)
            throw new JsonException($"Required property '{name}' is missing or null.");
        return property;
    }
    private static string ReadStringValue(JsonElement value) => value.ValueKind == JsonValueKind.String ? value.GetString()! : throw new JsonException("Expected a JSON string.");
    private static bool ReadBooleanValue(JsonElement value) => value.ValueKind is JsonValueKind.True or JsonValueKind.False ? value.GetBoolean() : throw new JsonException("Expected a JSON boolean.");
    private static int ReadInt32Value(JsonElement value) => value.TryGetInt32(out var result) ? result : throw new JsonException("Expected a 32-bit integer.");
    private static uint ReadUInt32Value(JsonElement value) => value.TryGetUInt32(out var result) ? result : throw new JsonException("Expected an unsigned 32-bit integer.");
    private static long ReadInt64Value(JsonElement value) => value.TryGetInt64(out var result) ? result : throw new JsonException("Expected a 64-bit integer.");
    private static ulong ReadUInt64Value(JsonElement value) => value.TryGetUInt64(out var result) ? result : throw new JsonException("Expected an unsigned 64-bit integer.");
    private static double ReadDoubleValue(JsonElement value) => value.TryGetDouble(out var result) ? result : throw new JsonException("Expected a number.");
    private static float ReadSingleValue(JsonElement value) => value.TryGetSingle(out var result) ? result : throw new JsonException("Expected a number.");
    private static List<T> ReadList<T>(JsonElement value, Func<JsonElement, T> read)
    {
        if (value.ValueKind != JsonValueKind.Array) throw new JsonException("Expected a JSON array.");
        var result = new List<T>();
        foreach (var item in value.EnumerateArray()) result.Add(read(item));
        return result;
    }
    private static Dictionary<string, string> ReadStringDictionary(JsonElement value)
    {
        if (value.ValueKind != JsonValueKind.Object) throw new JsonException("Expected a JSON object.");
        var result = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var item in value.EnumerateObject()) result.Add(item.Name, ReadStringValue(item.Value));
        return result;
    }
    private static Dictionary<string, JsonElement> ReadElementDictionary(JsonElement value)
    {
        if (value.ValueKind != JsonValueKind.Object) throw new JsonException("Expected a JSON object.");
        var result = new Dictionary<string, JsonElement>(StringComparer.Ordinal);
        foreach (var item in value.EnumerateObject()) result.Add(item.Name, item.Value.Clone());
        return result;
    }
    private static Dictionary<string, JsonElement>? ReadExtensionData(JsonElement value, params string[] knownProperties)
    {
        var result = new Dictionary<string, JsonElement>(StringComparer.Ordinal);
        foreach (var item in value.EnumerateObject())
        {
            if (Array.IndexOf(knownProperties, item.Name) < 0) result.Add(item.Name, item.Value.Clone());
        }
        return result.Count == 0 ? null : result;
    }
}
